argv:
set timeout 60
proc fail {code} {
  catch {send -- "\003"}
  after 300
  catch {close}
  catch {wait}
  exit $code
}
spawn env QWEN_TUI_RENDERER=opentui QWEN_CODE_SKIP_UPDATE_CHECK_ONCE=true bun packages/cli/dist/index.js
expect {
  -re {ready · click cards} { fail 1 }
  -re {Ask.*anything} {}
  -re {unexpected critical error|Error:} { fail 2 }
  timeout { fail 3 }
}
send -- "\003"
expect {
  eof {}
  timeout { fail 4 }
}
